import pandas as pd, re

df = pd.read_excel('/root/ERP-2025-table10.xls', sheet_name='B10', header=None)

def parse_year(val):
    if not isinstance(val,str):
        return None
    s = val.strip()
    if re.fullmatch(r'\d{4}\.', s):
        return int(s[:-1])
    return None

for idx, val in df[0].items():
    y = parse_year(val)
    if y and y>=2015:
        print(idx, val, df.loc[idx,1])
